import{_ as a,a0 as i,w as n,s as u,I as l,x as t,a1 as o,A as s,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"65% 的企业正致力于开源项目 | LCTT x X-CMD","titleTemplate":false,"description":"65% 的企业正致力于开源项目 | LCTT (201606) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"65% 的企业正致力于开源项目 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"65% 的企业正致力于开源项目 | LCTT (201606) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201606/20160510 65_percent of companies are contributing to open source projects","title":"65% 的企业正致力于开源项目","tag":"201606","desc":""},"relativePath":"201606/20160510 65_percent of companies are contributing to open source projects.md","filePath":"[post].md"}'),d={name:"201606/20160510 65_percent of companies are contributing to open source projects.md"};function f(m,e,b,k,h,C){const r=i("Link");return n(),u("div",null,[e[16]||(e[16]=l("h1",{id:"_65-的企业正致力于开源项目",tabindex:"-1"},[t("65% 的企业正致力于开源项目 "),l("a",{class:"header-anchor",href:"#_65-的企业正致力于开源项目","aria-label":"Permalink to “65% 的企业正致力于开源项目”"},"​")],-1)),e[17]||(e[17]=l("p",null,[l("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/images/business/BUSINESS_openseries.png?itok=s7lXChId",alt:""})],-1)),e[18]||(e[18]=l("p",null,"今年 Black Duck 和 North Bridge 发布了第十届年度开源软件前景调查，来调查开源软件的发展趋势。今年这份调查的亮点在于，当前主流社会对开源软件的接受程度以及过去的十年中人们对开源软件态度的变化。",-1)),l("p",null,[o(r,{href:"http://www.slideshare.net/blackducksoftware/2016-future-of-open-source-survey-results"},{default:s(()=>[...e[0]||(e[0]=[t("2016 年的开源软件前景调查",-1)])]),_:1}),e[1]||(e[1]=t("，分析了来自约3400位专家的反馈。今年的调查中，开发者发表了他们的看法，大约 70% 的参与者是开发者。数据显示，安全专家的参与人数呈指数级增长，增长超过 450% 。他们的参与表明，开源社区开始逐渐关注开源软件中存在的安全问题，以及当新的技术出现时确保它们的安全性。",-1))]),l("p",null,[e[3]||(e[3]=t("Black Duck 的",-1)),o(r,{href:"https://info.blackducksoftware.com/OpenSourceRookies2015.html"},{default:s(()=>[...e[2]||(e[2]=[t("年度开源新秀奖",-1)])]),_:1}),e[4]||(e[4]=t(" 涉及到一些新出现的技术，如容器方面的 Docker 和 Kontena。容器技术这一年有了巨大的发展 ———— 76% 的受访者表示，他们的企业有一些使用容器技术的规划。而 59% 的受访者正准备使用容器技术完成大量的部署，从开发与测试，到内部与外部的生产环境部署。开发者社区已经把容器技术作为一种简单快速开发的方法。",-1))]),e[19]||(e[19]=p('<p>调查显示，几乎每个组织都有开发者致力于开源软件，这一点毫不惊讶。当像微软和苹果这样的大公司将它们的一些解决方案开源时，开发者就获得了更多的机会来参与开源项目。我非常希望这样的趋势会延续下去，让更多的软件开发者无论在工作中，还是工作之余都可以致力于开源项目。</p><h3 id="_2016-年调查结果中的一些要点" tabindex="-1">2016 年调查结果中的一些要点 <a class="header-anchor" href="#_2016-年调查结果中的一些要点" aria-label="Permalink to “2016 年调查结果中的一些要点”">​</a></h3><h4 id="商业价值" tabindex="-1">商业价值 <a class="header-anchor" href="#商业价值" aria-label="Permalink to “商业价值”">​</a></h4><ul><li>开源软件是发展战略中的一个重要元素，超过 65% 的受访者使用开源软件来加速软件开发的进度。</li><li>超过 55% 的受访者在生产环境中使用开源软件。</li></ul><h4 id="创新的原动力" tabindex="-1">创新的原动力 <a class="header-anchor" href="#创新的原动力" aria-label="Permalink to “创新的原动力”">​</a></h4><ul><li>受访者表示，开源软件的使用让软件开发更加快速灵活，从而推进了创新；同时加速了软件推向市场的时间，也极大地减少了与上司沟通的时间。</li><li>开源软件的优质解决方案，富有竞争力的特性，技术能力，以及可定制化的能力，也促进了更多的创新。</li></ul><h4 id="开源商业模式与投资的激增" tabindex="-1">开源商业模式与投资的激增 <a class="header-anchor" href="#开源商业模式与投资的激增" aria-label="Permalink to “开源商业模式与投资的激增”">​</a></h4><ul><li>更多不同商业模式的出现给开源企业带来了前所未有的价值。这些价值并不依赖于云服务和技术支持。</li><li>开源的私募融资在过去的五年内，已增长了将近四倍。</li></ul><h4 id="安全和管理" tabindex="-1">安全和管理 <a class="header-anchor" href="#安全和管理" aria-label="Permalink to “安全和管理”">​</a></h4><p>一流的开源安全与管理实践的发展，也没有跟上人们使用开源不断增长的步伐。尽管备受关注的开源项目近年来爆炸式地增长，调查结果却指出：</p><ul><li>50% 的企业在选择和批准开源代码这方面没有出台正式的政策。</li><li>47% 的企业没有正式的流程来跟踪开源代码，这就限制了它们对开源代码的了解，以及控制开源代码的能力。</li><li>超过三分之一的企业没有用于识别、跟踪和修复重大开源安全漏洞的流程。</li></ul><h4 id="不断增长的开源参与者" tabindex="-1">不断增长的开源参与者 <a class="header-anchor" href="#不断增长的开源参与者" aria-label="Permalink to “不断增长的开源参与者”">​</a></h4><p>调查结果显示，一个活跃的企业开源社区，激励创新，提供价值，共享情谊：</p><ul><li>67% 的受访者表示，它们积极鼓励开发者参与开源项目。</li><li>65% 的企业正致力于开源项目。</li><li>约三分之一的企业有专门为开源项目设置的全职岗位。</li><li>59% 的受访者参与开源项目以获得竞争优势。</li></ul><p>Black Duck 和 North Bridge 从今年的调查中了解到了很多，如安全，政策，商业模式等。我们很兴奋能够分享这些新发现。感谢我们的合作者，以及所有参与我们调查的受访者。这是一个伟大的十年，我很高兴我们可以肯定地说，开源的未来充满了无限可能。</p>',15)),l("p",null,[e[6]||(e[6]=t("想要了解更多内容，可以查看完整的",-1)),o(r,{href:"http://www.slideshare.net/blackducksoftware/2016-future-of-open-source-survey-results%C2%A0"},{default:s(()=>[...e[5]||(e[5]=[t("调查结果",-1)])]),_:1}),e[7]||(e[7]=t("。",-1))]),e[20]||(e[20]=l("hr",null,null,-1)),l("p",null,[e[9]||(e[9]=t("via: ",-1)),o(r,{href:"https://opensource.com/business/16/5/2016-future-open-source-survey"},{default:s(()=>[...e[8]||(e[8]=[t("https://opensource.com/business/16/5/2016-future-open-source-survey",-1)])]),_:1})]),l("p",null,[e[13]||(e[13]=t("作者：",-1)),o(r,{href:"https://opensource.com/users/blackduck2016"},{default:s(()=>[...e[10]||(e[10]=[t("Haidee LeClair",-1)])]),_:1}),e[14]||(e[14]=t(" 译者：",-1)),o(r,{href:"https://github.com/Cathon"},{default:s(()=>[...e[11]||(e[11]=[t("Cathon",-1)])]),_:1}),e[15]||(e[15]=t(" 校对：",-1)),o(r,{href:"https://github.com/wxy"},{default:s(()=>[...e[12]||(e[12]=[t("wxy",-1)])]),_:1})])])}const w=a(d,[["render",f]]);export{g as __pageData,w as default};
